import{_ as t,o as r,c as a,a3 as n}from"./chunks/framework.Crt1tuW8.js";const h=JSON.parse(`{"title":"Grille d'évaluation — Examen 1","description":"","frontmatter":{"title":"Grille d'évaluation — Examen 1"},"headers":[],"relativePath":"grilles/grille-examen1.md","filePath":"grilles/grille-examen1.md"}`),d={name:"grilles/grille-examen1.md"};function s(o,e,i,l,c,u){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="grille-d-evaluation-—-examen-1" tabindex="-1">Grille d&#39;évaluation — Examen 1 <a class="header-anchor" href="#grille-d-evaluation-—-examen-1" aria-label="Permalink to &quot;Grille d&#39;évaluation — Examen 1&quot;">​</a></h1><p>Examen <strong>sur papier</strong>, en classe. Matière : <strong>modules 1 à 3</strong> (modélisation, DDL, SQL).</p><table tabindex="0"><thead><tr><th>Partie</th><th>Matière</th><th style="text-align:right;">Points</th></tr></thead><tbody><tr><td>1</td><td>Modélisation</td><td style="text-align:right;">30</td></tr><tr><td>2</td><td>DDL</td><td style="text-align:right;">30</td></tr><tr><td>3</td><td>SQL</td><td style="text-align:right;">40</td></tr><tr><td></td><td><strong>Total</strong></td><td style="text-align:right;"><strong>100</strong></td></tr></tbody></table><h2 id="echelle-d-evaluation" tabindex="-1">Échelle d&#39;évaluation <a class="header-anchor" href="#echelle-d-evaluation" aria-label="Permalink to &quot;Échelle d&#39;évaluation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Niveau</th><th>Valeur</th></tr></thead><tbody><tr><td>Excellent</td><td>100 %</td></tr><tr><td>Suffisant</td><td>70 %</td></tr><tr><td>Insuffisant</td><td>40 %</td></tr><tr><td>Incorrect</td><td>0 %</td></tr></tbody></table><h2 id="correction-sur-papier" tabindex="-1">Correction sur papier <a class="header-anchor" href="#correction-sur-papier" aria-label="Permalink to &quot;Correction sur papier&quot;">​</a></h2><p>Le code étant écrit à la main, il n&#39;est pas exécuté. La correction porte sur la <strong>logique</strong> et sur la <strong>syntaxe enseignée</strong>, avec la distinction suivante :</p><table tabindex="0"><thead><tr><th>Type d&#39;écart</th><th>Traitement</th></tr></thead><tbody><tr><td>Point-virgule final, indentation, majuscules/minuscules des mots-clés</td><td>Non pénalisé</td></tr><tr><td>Nom de colonne approximatif mais sans ambiguïté (<code>date_spect.</code> pour <code>date_spectacle</code>)</td><td>Non pénalisé</td></tr><tr><td>Mot-clé manquant ou mal placé qui empêcherait l&#39;exécution (<code>from</code>, <code>where</code>, virgule entre colonnes)</td><td>Pénalisé — descendre d&#39;un niveau</td></tr><tr><td>Erreur de logique (mauvais filtre, mauvaise table, <code>and</code> au lieu de <code>or</code>)</td><td>Pénalisé selon la grille</td></tr><tr><td>Syntaxe d&#39;un autre SGBD (<code>serial</code>, <code>create type … as enum</code>, <code>ilike</code>, <code>~</code>)</td><td>Pénalisé — descendre d&#39;un niveau</td></tr></tbody></table><hr><h2 id="partie-1-—-modelisation-30-pts" tabindex="-1">Partie 1 — Modélisation (30 pts) <a class="header-anchor" href="#partie-1-—-modelisation-30-pts" aria-label="Permalink to &quot;Partie 1 — Modélisation (30 pts)&quot;">​</a></h2><h3 id="q1-—-reperer-les-cles-d-un-modele-6-pts" tabindex="-1">Q1 — Repérer les clés d&#39;un modèle (6 pts) <a class="header-anchor" href="#q1-—-reperer-les-cles-d-un-modele-6-pts" aria-label="Permalink to &quot;Q1 — Repérer les clés d&#39;un modèle (6 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Toutes les PK et les FK identifiées. Chaque FK est rattachée à la bonne table référencée.</td></tr><tr><td>Suffisant</td><td>Toutes les PK identifiées; une FK manquante ou rattachée à la mauvaise table.</td></tr><tr><td>Insuffisant</td><td>Confusion entre PK et FK, ou plusieurs clés omises.</td></tr><tr><td>Incorrect</td><td>Les clés ne sont pas repérées.</td></tr></tbody></table><hr><h3 id="q2-—-determiner-et-justifier-les-cardinalites-8-pts" tabindex="-1">Q2 — Déterminer et justifier les cardinalités (8 pts) <a class="header-anchor" href="#q2-—-determiner-et-justifier-les-cardinalites-8-pts" aria-label="Permalink to &quot;Q2 — Déterminer et justifier les cardinalités (8 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Chaque relation est correctement qualifiée (1–N, N–N) et justifiée par un exemple concret dans les deux sens.</td></tr><tr><td>Suffisant</td><td>Cardinalités correctes mais justification absente ou donnée dans un seul sens.</td></tr><tr><td>Insuffisant</td><td>Une cardinalité sur deux est correcte, ou la table associative n&#39;est pas reconnue comme telle.</td></tr><tr><td>Incorrect</td><td>Cardinalités majoritairement erronées.</td></tr></tbody></table><hr><h3 id="q3-—-interpreter-le-modele-6-pts" tabindex="-1">Q3 — Interpréter le modèle (6 pts) <a class="header-anchor" href="#q3-—-interpreter-le-modele-6-pts" aria-label="Permalink to &quot;Q3 — Interpréter le modèle (6 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>La table qui représente une action est reconnue et expliquée. L&#39;emplacement de chaque information demandée est correctement localisé, y compris l&#39;information qui <strong>ne se stocke pas</strong> parce qu&#39;elle se calcule.</td></tr><tr><td>Suffisant</td><td>Localisations correctes, mais l&#39;information calculée est présentée comme une colonne à stocker.</td></tr><tr><td>Insuffisant</td><td>Plusieurs informations mal localisées.</td></tr><tr><td>Incorrect</td><td>Le modèle n&#39;est pas interprété.</td></tr></tbody></table><hr><h3 id="q4-—-construire-un-modele-a-partir-de-regles-d-affaires-10-pts" tabindex="-1">Q4 — Construire un modèle à partir de règles d&#39;affaires (10 pts) <a class="header-anchor" href="#q4-—-construire-un-modele-a-partir-de-regles-d-affaires-10-pts" aria-label="Permalink to &quot;Q4 — Construire un modèle à partir de règles d&#39;affaires (10 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Toutes les tables nécessaires sont présentes, avec des colonnes et des types appropriés. PK, FK et cardinalités indiquées. La FK est placée du bon côté de la relation 1–N. Conventions de nommage respectées (minuscules, sans accents, singulier, <code>snake_case</code>).</td></tr><tr><td>Suffisant</td><td>Modèle fonctionnel, mais un type mal choisi, une FK placée du mauvais côté, ou des conventions de nommage non respectées.</td></tr><tr><td>Insuffisant</td><td>Une table manquante, ou les relations entre les tables ne sont pas exprimées par des clés.</td></tr><tr><td>Incorrect</td><td>Modèle absent ou sans rapport avec les règles d&#39;affaires.</td></tr></tbody></table><hr><h2 id="partie-2-—-ddl-30-pts" tabindex="-1">Partie 2 — DDL (30 pts) <a class="header-anchor" href="#partie-2-—-ddl-30-pts" aria-label="Permalink to &quot;Partie 2 — DDL (30 pts)&quot;">​</a></h2><h3 id="q5-—-identifier-les-erreurs-d-un-script-10-pts" tabindex="-1">Q5 — Identifier les erreurs d&#39;un script (10 pts) <a class="header-anchor" href="#q5-—-identifier-les-erreurs-d-un-script-10-pts" aria-label="Permalink to &quot;Q5 — Identifier les erreurs d&#39;un script (10 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Toutes les erreurs sont relevées et chacune est <strong>expliquée</strong> (pourquoi le script échoue à cet endroit).</td></tr><tr><td>Suffisant</td><td>La majorité des erreurs est relevée; une ou deux omissions, ou des explications superficielles.</td></tr><tr><td>Insuffisant</td><td>Moins de la moitié des erreurs relevée, ou erreurs relevées sans explication.</td></tr><tr><td>Incorrect</td><td>Les erreurs ne sont pas identifiées.</td></tr></tbody></table><hr><h3 id="q6-—-reecrire-le-script-corrige-8-pts" tabindex="-1">Q6 — Réécrire le script corrigé (8 pts) <a class="header-anchor" href="#q6-—-reecrire-le-script-corrige-8-pts" aria-label="Permalink to &quot;Q6 — Réécrire le script corrigé (8 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Script complet et exécutable : <code>use</code> présent, tables créées dans le bon ordre, types de FK identiques aux PK référencées, <code>enum</code> déclaré dans la colonne, <code>auto_increment</code> sur une clé.</td></tr><tr><td>Suffisant</td><td>Script globalement correct, mais un élément manque (le <code>use</code>, une contrainte, l&#39;ordre de création).</td></tr><tr><td>Insuffisant</td><td>Plusieurs erreurs relevées en Q5 subsistent dans la réécriture.</td></tr><tr><td>Incorrect</td><td>Script non réécrit ou toujours non fonctionnel dans son ensemble.</td></tr></tbody></table><hr><h3 id="q7-—-ecrire-un-create-table-complet-12-pts" tabindex="-1">Q7 — Écrire un <code>create table</code> complet (12 pts) <a class="header-anchor" href="#q7-—-ecrire-un-create-table-complet-12-pts" aria-label="Permalink to &quot;Q7 — Écrire un `create table` complet (12 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Clé primaire auto-incrémentée. Types appropriés à la nature de chaque donnée. Contraintes pertinentes (<code>not null</code>, <code>unique</code>, <code>check</code>, valeur par défaut). Clé étrangère correctement déclarée et du bon type.</td></tr><tr><td>Suffisant</td><td>Table fonctionnelle, mais un type discutable ou une contrainte pertinente omise.</td></tr><tr><td>Insuffisant</td><td>Table créée, mais clé primaire ou clé étrangère absente ou mal déclarée.</td></tr><tr><td>Incorrect</td><td>Instruction non fonctionnelle ou absente.</td></tr></tbody></table><div class="my-6 rounded-lg border border-blue-300 bg-blue-50 p-4 text-blue-900"><strong>Sur le choix des types</strong><br> Un type est « approprié » s&#39;il correspond à l&#39;usage réel de la donnée, pas seulement à son apparence. Un numéro sur lequel on ne calcule jamais et qui peut commencer par un zéro est une chaîne, pas un entier — c&#39;est ce raisonnement qui est évalué, et il doit pouvoir être justifié. </div><hr><h2 id="partie-3-—-sql-40-pts" tabindex="-1">Partie 3 — SQL (40 pts) <a class="header-anchor" href="#partie-3-—-sql-40-pts" aria-label="Permalink to &quot;Partie 3 — SQL (40 pts)&quot;">​</a></h2><h3 id="q8-—-insertion-6-pts" tabindex="-1">Q8 — Insertion (6 pts) <a class="header-anchor" href="#q8-—-insertion-6-pts" aria-label="Permalink to &quot;Q8 — Insertion (6 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Colonnes listées explicitement. Valeurs dans le bon ordre et du bon type. Les colonnes automatiques ou à valeur par défaut sont omises à bon escient. Insertion multiple en une seule instruction là où c&#39;est demandé.</td></tr><tr><td>Suffisant</td><td>Insertion valide, mais colonnes non listées, ou une colonne à valeur par défaut fournie inutilement.</td></tr><tr><td>Insuffisant</td><td>Insertion tentée mais nombre de valeurs ne correspondant pas aux colonnes, ou types incompatibles.</td></tr><tr><td>Incorrect</td><td>Aucune insertion fonctionnelle.</td></tr></tbody></table><hr><h3 id="q9-—-predire-le-resultat-de-requetes-8-pts" tabindex="-1">Q9 — Prédire le résultat de requêtes (8 pts) <a class="header-anchor" href="#q9-—-predire-le-resultat-de-requetes-8-pts" aria-label="Permalink to &quot;Q9 — Prédire le résultat de requêtes (8 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Les lignes retournées sont exactes pour chaque requête, y compris l&#39;ordre lorsqu&#39;un <code>order by</code> est présent. Les cas liés à la collation (casse et accents ignorés) sont traités correctement.</td></tr><tr><td>Suffisant</td><td>Une requête sur quatre est mal évaluée, ou l&#39;ordre est ignoré.</td></tr><tr><td>Insuffisant</td><td>La moitié des requêtes est mal évaluée, ou les bornes de <code>between</code> et l&#39;effet de <code>distinct</code> ne sont pas maîtrisés.</td></tr><tr><td>Incorrect</td><td>Les résultats annoncés ne correspondent pas aux données.</td></tr></tbody></table><hr><h3 id="q10-—-selection-et-filtres-10-pts" tabindex="-1">Q10 — Sélection et filtres (10 pts) <a class="header-anchor" href="#q10-—-selection-et-filtres-10-pts" aria-label="Permalink to &quot;Q10 — Sélection et filtres (10 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Colonnes demandées exactement. Filtres corrects, y compris les opérateurs (<code>between</code>, <code>in</code>, <code>like</code>, <code>not</code>, <code>and</code>/<code>or</code>). Tri conforme à l&#39;énoncé. <code>distinct</code> employé là où des doublons sont attendus.</td></tr><tr><td>Suffisant</td><td>Requêtes fonctionnelles, mais tri absent, colonne superflue, ou borne d&#39;intervalle inexacte.</td></tr><tr><td>Insuffisant</td><td>Logique de filtre majoritairement incorrecte, ou <code>and</code>/<code>or</code> intervertis.</td></tr><tr><td>Incorrect</td><td>Requêtes non fonctionnelles.</td></tr></tbody></table><hr><h3 id="q11-—-sous-requete-non-correlee-8-pts" tabindex="-1">Q11 — Sous-requête non corrélée (8 pts) <a class="header-anchor" href="#q11-—-sous-requete-non-correlee-8-pts" aria-label="Permalink to &quot;Q11 — Sous-requête non corrélée (8 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Sous-requête placée dans le <code>where</code> et retournant <strong>une seule colonne</strong>. Opérateur approprié (<code>in</code>, <code>not in</code>, <code>any</code>, <code>all</code>). Résultat conforme à la demande.</td></tr><tr><td>Suffisant</td><td>Logique correcte, mais opérateur mal choisi (ex. <code>in</code> là où <code>not in</code> est attendu) ou sous-requête retournant plus d&#39;une colonne.</td></tr><tr><td>Insuffisant</td><td>Sous-requête tentée mais reliée à la mauvaise clé, donc ciblant les mauvaises lignes.</td></tr><tr><td>Incorrect</td><td>Aucune sous-requête, ou requête non fonctionnelle.</td></tr></tbody></table><hr><h3 id="q12-—-mise-a-jour-et-suppression-ciblees-8-pts" tabindex="-1">Q12 — Mise à jour et suppression ciblées (8 pts) <a class="header-anchor" href="#q12-—-mise-a-jour-et-suppression-ciblees-8-pts" aria-label="Permalink to &quot;Q12 — Mise à jour et suppression ciblées (8 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td><code>where</code> présent et ciblant exactement les lignes demandées. Aucune ligne non visée ne serait affectée. Sous-requête employée là où elle est exigée.</td></tr><tr><td>Suffisant</td><td>Ciblage correct mais imprécis : le filtre affecterait quelques lignes de plus que demandé.</td></tr><tr><td>Insuffisant</td><td><code>update</code> ou <code>delete</code> structurellement correct mais ciblant les mauvaises lignes.</td></tr><tr><td>Incorrect</td><td>Instruction sans <code>where</code>, ou non fonctionnelle.</td></tr></tbody></table><div class="my-6 rounded-lg border border-red-300 bg-red-50 p-4 text-red-900"><strong>Cas particulier</strong><br> Un <code>update</code> ou un <code>delete</code> <strong>sans clause <code>where</code></strong> affecterait toute la table : la question est cotée <strong>Incorrect</strong>, même si le reste de l&#39;instruction est bien écrit. </div>',49)])])}const m=t(d,[["render",s]]);export{h as __pageData,m as default};
